outputs.summary:
{
  "name": "Contiguous US Economic Distress Index Choropleth",
  "description": "Acquire 2017–2021 ACS 5-year county data and boundaries, calculate the county-level Economic Distress Index, project geometries to Conus Albers, and create a five-class Jenks choropleth map with the reversed Lajolla palette.",
  "steps": [
    {
      "step_id": "acquire_data",
      "agent_id": "geospatial_data_discovery_agent",
      "instructions": "Acquire county boundary geometries for the contiguous United States and the 2017–2021 ACS 5-year variables required to calculate a county-level Economic Distress Index, preserving source, vintage, geographic coverage, identifiers, units, and provenance."
    },
    {
      "step_id": "prepare_index_data",
      "agent_id": "vector_gis_agent",
      "depends_on": [
        "acquire_data"
      ],
      "instructions": "Using the acquired county geometries and ACS attributes, create a county-level dataset for the contiguous United States, calculate the Economic Distress Index using a defensible documented definition supported by the available ACS variables, and project the county geometries to Conus Albers before delivering the map-ready artifact.",
      "handoff_brief": "The required geography is the contiguous United States, and the required ACS vintage is 2017–2021 5-year estimates."
    },
    {
      "step_id": "create_map",
      "agent_id": "cartography_geovisualization_agent",
      "depends_on": [
        "prepare_index_data"
      ],
      "instructions": "Create a county-level choropleth map from the projected Economic Distress Index dataset using five Natural Breaks (Jenks) classes, the reversed Lajolla sequential color palette, and a horizontal colorbar with lower values on the left and higher values on the right.",
      "handoff_brief": "The county geometries have been projected to Conus Albers and the map must represent the 2017–2021 ACS-based Economic Distress Index for the contiguous United States."
    }
  ]
}
